function parseRoutingDiagnostics(raw: string): { difficulty: string; chosenEndpointId: string | null } {
  const defaults = {
    difficulty: "unknown",
    chosenEndpointId: null as string | null,
  };

  if (typeof raw !== "string") {
    return defaults;
  }

  try {
    const parsed: unknown = JSON.parse(raw);

    if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
      return defaults;
    }

    const obj = parsed as Record<string, unknown>;

    const difficulty =
      typeof obj.difficulty === "string" && obj.difficulty.trim() !== ""
        ? obj.difficulty
        : defaults.difficulty;

    const chosenEndpointId =
      typeof obj.chosenEndpointId === "string"
        ? obj.chosenEndpointId
        : obj.chosenEndpointId === null
        ? null
        : defaults.chosenEndpointId;

    return { difficulty, chosenEndpointId };
  } catch {
    return defaults;
  }
}
